var HelpCommand = class extends import_framework5.Command {
  name = "help";
  description = "Browse all 690+ commands with an interactive category menu";
  registerApplicationCommands(registry) {
    registry.registerChatInputCommand(
      new import_discord7.SlashCommandBuilder().setName("help").setDescription("Browse all 690+ commands with an interactive category menu").addStringOption((o) => o.setName("input").setDescription("A specific command name").setRequired(false))
    );
  }
  async chatInputRun(interaction2) {
    const query = interaction2.options.getString("input");
    if (query) {
      const entry = CATALOG.find((e) => e.n === query.toLowerCase());
      if (!entry) {
        return interaction2.reply({ embeds: [errEmbed(`No command named **${query}**. Try \`/help\` to browse categories.`)], ephemeral: true });
      }
      const meta = CATEGORY_META[entry.c];
      const embed2 = brandEmbed().setTitle(`${meta?.emoji ?? "\u{1F48E}"} ${entry.n}`).setDescription(entry.d).addFields(
        { name: "Category", value: `${meta?.label ?? entry.c}`, inline: true },
        { name: "Type", value: entry.ctx ? "Context menu" : "Slash + prefix", inline: true },
        { name: "Dashboards", value: "Customize this module in the web dashboard", inline: true }
      );
      return interaction2.reply({ embeds: [embed2], ephemeral: true });
    }
    const categories = COMMAND_CATEGORIES.filter((c) => CATALOG.some((e) => e.c === c));
    const options = categories.slice(0, 25).map((c) => ({
      label: `${CATEGORY_META[c].label} (${CATALOG.filter((e) => e.c === c).length})`,
      value: c,
      emoji: CATEGORY_META[c].emoji
    }));
    const menu = new import_discord7.ActionRowBuilder().addComponents(
      new import_discord7.StringSelectMenuBuilder().setCustomId("help:category").setPlaceholder("Select a category\u2026").addOptions(options)
    );
    const total = CATALOG.length;
    const embed = brandEmbed().setTitle(`${BRAND.emoji} Sapphire \u2014 ${total} commands`).setDescription(
      `Sapphire ships **${total} commands** across **${categories.length} categories**, every one of them customizable from the web dashboard.

Pick a category below to explore it.`
    );
    const message = await interaction2.reply({ embeds: [embed], components: [menu], fetchReply: true });
    const collector = message.createMessageComponentCollector({
      componentType: import_discord7.ComponentType.StringSelect,
      time: 12e4
    });
    collector.on("collect", async (select) => {
      const category = select.values[0];
      const meta = CATEGORY_META[category];
      const entries = CATALOG.filter((e) => e.c === category);
      const lines = entries.map((e) => `\`/${e.n}\` \u2014 ${e.d}`);
      const chunked = [];
      let page = "";
      for (const line of lines) {
        if (page.length + line.length > 3800) {
          chunked.push(page);
          page = "";
        }
        page += `${line}
`;
      }
      chunked.push(page);
      await select.update({
        embeds: [
          brandEmbed().setTitle(`${meta.emoji} ${meta.label} \u2014 ${entries.length} commands`).setDescription(chunked[0]).setFooter({ text: chunked.length > 1 ? `Page 1/${chunked.length}` : "Sapphire" })
        ]
      });
    });
  }
};
