async function resolveTarget(interaction2) {
  const user = interaction2.options.getUser("user", true);
  const member = interaction2.guild?.members.cache.get(user.id) ?? null;
  return { member, user };
}
async function createCase(guildId, data) {
  const db = import_framework6.container.db;
  const row = db.db.prepare("SELECT COALESCE(MAX(caseId), 0) + 1 AS next FROM cases WHERE guildId = ?").get(guildId);
  const caseId = row.next;
  db.db.prepare(
    `INSERT INTO cases (guildId, caseId, userId, moderatorId, type, reason, duration, createdAt, expiresAt)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(guildId, caseId, data.userId, data.moderatorId, data.type, data.reason, data.duration ?? 0, Date.now(), data.duration ? Date.now() + (data.duration ?? 0) : 0);
  await postModlog(guildId, caseId, data);
  return caseId;
}
async function postModlog(guildId, caseId, data) {
  const mod = import_framework6.container.settings.moderation(guildId);
  if (!mod.modLogChannelId) return;
  const guild = import_framework6.container.client.guilds.cache.get(guildId);
  const channel = guild?.channels.cache.get(mod.modLogChannelId);
  if (channel?.isTextBased()) {
    const embed = brandEmbed(EMBED_COLORS.primary).setTitle(`Case #${caseId} \u2014 ${data.type}`).addFields(
      { name: "User", value: `<@${data.userId}>`, inline: true },
      { name: "Moderator", value: `<@${data.moderatorId}>`, inline: true },
      { name: "Reason", value: data.reason || "No reason provided" }
    ).setFooter({ text: `User ID: ${data.userId}` }).setTimestamp();
    if (data.duration) embed.addFields({ name: "Duration", value: formatDuration(data.duration), inline: true });
    await channel.send({ embeds: [embed] }).catch(() => null);
  }
}
async function dmAction(member, guildId, action, reason) {
  const mod = import_framework6.container.settings.moderation(guildId);
  if (!mod.dmOnAction || !member) return;
  const guild = import_framework6.container.client.guilds.cache.get(guildId);
  await member.send({
    embeds: [
      brandEmbed(15844367).setTitle("\u{1F6E1}\uFE0F Moderation action").setDescription(`You received a **${action}** in **${guild?.name ?? "a server"}**.
**Reason:** ${reason}`)
    ]
  }).catch(() => null);
}
