function progressLine(xp, level) {
  const needed = xpForLevel(level);
  const current = xpForLevel(level - 1 < 0 ? 0 : level - 1);
  const pct = Math.min(100, Math.round((xp - current) / Math.max(1, needed - current) * 100));
  return `${"\u2593".repeat(Math.floor(pct / 10))}${"\u2591".repeat(10 - Math.floor(pct / 10))} ${pct}%`;
}
